-- Historical catalog before WebP conversion, retained to verify migration of all existing IDs and answers.
-- Test fixture only: do not regenerate when updating the current catalog.
-- Canonical names/centroids come from server/data/campus-buildings.json.
-- Only weekly-images photos enter the Weekly pool. Custom photo rows are preserved.

ON CONFLICT(image_id) DO UPDATE SET
  image_path = excluded.image_path,
  photo_pool = excluded.photo_pool,
  answer_latitude = excluded.answer_latitude,
  answer_longitude = excluded.answer_longitude,
  answer_building_name = excluded.answer_building_name,
  answer_building_latitude = excluded.answer_building_latitude,
  answer_building_longitude = excluded.answer_building_longitude;
